fn contained(root: &Path, relative: &Path) -> Result<PathBuf> {
    if relative.as_os_str().is_empty()
        || relative
            .components()
            .any(|c| !matches!(c, Component::Normal(_) | Component::CurDir))
    {
        return Err(format!(
            "expected a repository-relative path without '..': {}",
            relative.display()
        ));
    }
    let path = root
        .join(relative)
        .canonicalize()
        .map_err(|e| format!("{}: {e}", relative.display()))?;
    if !path.starts_with(root) {
        return Err(format!("path escapes repository: {}", relative.display()));
    }
    Ok(path)
}

fn read(root: &Path, relative: &Path) -> Result<String> {
    fs::read_to_string(contained(root, relative)?)
        .map_err(|e| format!("{}: {e}", relative.display()))
}

pub fn snapshot(root: &Path, path: &str, start: usize, end: usize) -> Result<Input> {
    let root = root.canonicalize().map_err(|e| e.to_string())?;
    let text = read(&root, Path::new(path))?;
    Ok(Input {
        path: path.into(),
        line_start: start,
        line_end: end,
        contents: lines(&text, start, end)?,
    })
}

fn input_files_must_exist_be_utf8_and_stay_inside_repository() {
    let f = Fixture::new();
    for path in ["missing.rs", "../outside", "/etc/passwd", ""] {
        assert!(snapshot(&f.0, path, 1, 1).is_err());
    }
    fs::write(f.0.join("binary"), [0xff]).unwrap();
    assert!(snapshot(&f.0, "binary", 1, 1).is_err());
}

fn escaping_symlinks_are_rejected() {
    let f = Fixture::new();
    let outside = Fixture::new();
    std::os::unix::fs::symlink(outside.0.join("src/code.rs"), f.0.join("escape")).unwrap();
    assert!(
        snapshot(&f.0, "escape", 1, 1)
            .unwrap_err()
            .contains("escapes")
    );
}

fn repository_contained_symlink_is_allowed() {
    let f = Fixture::new();
    std::os::unix::fs::symlink("src/code.rs", f.0.join("inside")).unwrap();
    assert_eq!(snapshot(&f.0, "inside", 1, 1).unwrap().contents, "first\n");
}
